func (c *CLab) Destroy(ctx context.Context, options ...DestroyOption) (err error) {
	opts := NewDestroyOptions()

	for _, opt := range options {
		opt(opts)
	}

	if c.LabRuntime != nil {
		return c.destroyWithLabRuntime(ctx, opts)
	}

	var containers []clabruntime.GenericContainer

	switch {
	case opts.all:
		containers, err = c.ListContainers(ctx)
	case c.TopoPaths.TopologyFilenameAbsPath() != "":
		containers, err = c.ListNodesContainersIgnoreNotFound(ctx)
		if err == nil {
			var tailscaleContainers []clabruntime.GenericContainer
			tailscaleContainers, err = c.discoverTailscaleContainers(ctx, opts.nodeFilter)
			containers = append(containers, tailscaleContainers...)
		}
	default:
		var listOpts []ListOption

		if c.Config.Name != "" {
			listOpts = []ListOption{WithListLabName(c.Config.Name)}
		} else {
			listOpts = []ListOption{WithListclabLabelExists()}
		}

		containers, err = c.ListContainers(ctx, listOpts...)
	}

	if err != nil {
		return err
	}

	// topo will hold the reference to the topology file
	// as the key and the respective lab directory as the referenced value
	topos := map[string]string{}

	for idx := range containers {
		topoFile, ok := containers[idx].Labels[clabconstants.TopoFile]
		if !ok {
			continue
		}

		topos[topoFile] = filepath.Dir(containers[idx].Labels[clabconstants.NodeLabDir])
	}

	// failedLabDirs records the lab directories whose destroy failed or was never
	// attempted. --cleanup keeps those directories: deleting the lab directory of
	// a lab that is still running would discard the state file destroy needs for
	// its management network cleanup on the next attempt.
	failedLabDirs := map[string]bool{}

	defer func() {
		if opts.cleanup {
			if cleanupErr := c.destroyLabDirs(topos, opts.all, failedLabDirs); cleanupErr != nil {
				err = errors.Join(err, cleanupErr)
			}
		}
	}()

	if len(topos) == 0 {
		return nil
	}

	log.Debugf("got the following topologies for destroy: %+v", topos)

	// if all, and cli doesn't have --yes flag, and in a terminal -- prompt user confirmation
	if opts.all && opts.terminalPrompt && term.IsTerminal(int(os.Stdin.Fd())) {
		err := cliPromptToDestroyAll(topos)
		if err != nil {
			return err
		}
	}

	var errs []error

	for topo, labDir := range topos {
		cc, err := c.makeCopyForDestroy(ctx, topo, labDir, *opts)
		if err != nil {
			log.Errorf("error creating clab instance for topo %q: %v", topo, err)

			errs = append(errs, fmt.Errorf(
				"error creating clab instance for topo %q: %w", topo, err))
			failedLabDirs[labDir] = true

			continue
		}

		err = cc.destroy(ctx, opts.maxWorkers, opts.keepMgmtNet)
		if err != nil {
			log.Errorf("Error occurred during the %s lab deletion: %v", cc.Config.Name, err)
			errs = append(errs, err)
			failedLabDirs[labDir] = true
		}
	}

	if len(errs) != 0 {
		return fmt.Errorf("error(s) occurred during the deletion. Check log messages")
	}

	return nil
}

// creates a mostly cloned version of the current c but set to the new topology, and with the
// necessary steps (mgmt network things) handled preparing the new CLab for destruction.
func (c *CLab) makeCopyForDestroy(
	ctx context.Context,
	topo,
	labDir string,
	opts DestroyOptions,
) (*CLab, error) {
	newOpts := []ClabOption{
		WithTimeout(c.timeout),
	}

	// Try to load topology file if it exists, otherwise use lab name only.
	// This allows destroying labs even when the topology file has been deleted.
	// WithTopoPath / WithLabNameOnly must run before WithNodeFilter so filterClabNodes
	// sees topology nodes (see filterClabNodes in clab.go).
	varsFiles := opts.varsFiles
	if len(varsFiles) == 0 {
		varsFiles = c.TopoPaths.VarsFilenamesAbsPath()
	}

	if clabutils.FileOrDirExists(topo) {
		newOpts = append(newOpts, WithTopoPath(topo, varsFiles))
	} else {
		// Derive lab name from lab directory (format: clab-<labname>)
		labName := filepath.Base(labDir)
		labName = strings.TrimPrefix(labName, "clab-")
		log.Debugf("topology file %q not found, using lab name %q for destroy", topo, labName)
		newOpts = append(newOpts, WithLabNameOnly(labName))
	}

	newOpts = append(newOpts,
		WithNodeFilter(opts.nodeFilter),
		// during destroy we don't want to check bind paths
		// as it is irrelevant for this command.
		WithSkippedBindsPathsCheck(),
		WithRuntime(
			c.globalRuntimeName,
			&clabruntime.RuntimeConfig{
				Debug:            c.Config.Debug,
				Timeout:          c.timeout,
				GracefulShutdown: opts.graceful,
			},
		),
	)

	if opts.keepMgmtNet {
		newOpts = append(newOpts, WithKeepMgmtNet())
	}

	cc, err := NewContainerLab(newOpts...)
	if err != nil {
		return nil, err
	}
	if labDir != "" && clabutils.FileOrDirExists(labDir) {
		// adjust the labdir. Usually we take the PWD. but now on destroy time,
		// we might be in a different Dir.
		err = cc.TopoPaths.SetLabDir(labDir)
		if err != nil {
			return nil, err
		}
	}

	err = clablinks.SetMgmtNetUnderlyingBridge(cc.Config.Mgmt.Bridge)
	if err != nil {
		return nil, err
	}

	// populate the management network state (bridge names) destroy needs for the
	// removal of the iptables rules, without creating networks that are missing:
	// a lab deployed with a management network override leaves the topology's
	// default network uncreated, and creating it here would collide with the
	// subnets the override is using.
	if !cc.mgmtNetworksSkipped() {
		var bridged clabtypes.MgmtNetworks
		for _, m := range cc.allMgmtNetworks() {
			if m.Driver != clabtypes.MgmtDriverMacvlan {
				bridged = append(bridged, m)
			}
		}
		if err = cc.resolveMgmtNetworksForDestroy(ctx, bridged); err != nil {
			return nil, err
		}
	}

	err = cc.ResolveLinks()
	if err != nil {
		return nil, err
	}

	return cc, nil
}

// resolveMgmtNetworksForDestroy inspects the management networks that already exist
// so their bridge names are populated for the iptables cleanup. Networks that do not
// exist are skipped: they hold no bridge to clean up, and destroy must not create
// management networks. Runtimes that cannot check network existence keep the
// create-or-inspect behavior.
func (c *CLab) resolveMgmtNetworksForDestroy(
	ctx context.Context,
	networks clabtypes.MgmtNetworks,
) error {
	var existing clabtypes.MgmtNetworks

	for _, m := range networks {
		rt, rtErr := c.mgmtRuntime(c.globalRuntimeName, m)
		if rtErr != nil {
			// runtimes without multiple network support never created extra networks
			log.Debug(
				"Skipping management network resolution", "network", m.Network, "error", rtErr,
			)
			continue
		}

		checker, ok := rt.(clabruntime.MgmtNetworkChecker)
		if !ok {
			existing = append(existing, m)
			continue
		}

		exists, err := checker.MgmtNetworkExists(ctx)
		if err != nil {
			return err
		}
		if !exists {
			log.Debug("Skipping management network that does not exist", "network", m.Network)
			continue
		}

		existing = append(existing, m)
	}

	return c.createNetworks(ctx, existing)
}

// destroyLabDirs removes the lab directories of the destroyed labs. Directories
// recorded in failedLabDirs are kept: their labs are still running, and the
// directory holds the lab state a later destroy attempt relies on.
func (c *CLab) destroyLabDirs(
	topos map[string]string,
	all bool,
	failedLabDirs map[string]bool,
) error {
	if len(topos) == 0 {
		log.Info("no containerlab containers found")

		if !all {
			labDir := c.TopoPaths.TopologyLabDir()
			if labDir == "" {
				// Try to infer the precise lab directory when TopologyLabDir is not set,
				// e.g. destroy --name without topology file. Only look for an exact
				// clab-<name> match, never a wildcard.
				if c.Config != nil && c.Config.Name != "" {
					candidates := []string{}
					if base := os.Getenv("CLAB_LABDIR_BASE"); base != "" {
						candidates = append(candidates, filepath.Join(base, "clab-"+c.Config.Name))
					}
					if c.TopoPaths.TopologyFileIsSet() {
						candidates = append(
							candidates,
							filepath.Join(c.TopoPaths.TopologyFileDir(), "clab-"+c.Config.Name),
						)
					} else {
						if wd, err := os.Getwd(); err == nil && wd != "" {
							candidates = append(
								candidates,
								filepath.Join(wd, "clab-"+c.Config.Name),
							)
						}
					}
					for _, cand := range candidates {
						if _, err := os.Stat(cand); err == nil {
							labDir = cand
							break
						}
					}
					if labDir == "" {
						log.Info(
							"lab directory not found, nothing to clean",
							"candidates",
							candidates,
						)
						return nil
					}
				} else {
					log.Info("lab directory not found, nothing to clean")
					return nil
				}
			}

			// Safety: only remove directories that look like a lab directory.
			base := filepath.Base(labDir)
			if !strings.HasPrefix(base, "clab-") {
				log.Warnf("refusing to remove lab directory %q: unexpected name", labDir)
				return nil
			}
			if c.Config != nil && c.Config.Name != "" {
				expected := "clab-" + c.Config.Name
				if base != expected {
					log.Warnf(
						"refusing to remove lab directory %q: does not match expected %q",
						labDir,
						expected,
					)
					return nil
				}
			}

			if _, err := os.Stat(labDir); os.IsNotExist(err) {
				log.Info("lab directory not found, nothing to clean", "path", labDir)
				return nil
			} else if err != nil {
				log.Debug("failed to stat lab directory, skipping", "path", labDir, "error", err)
				return nil
			}

			log.Info("Removing lab directory", "path", labDir)
			if err := os.RemoveAll(labDir); err != nil {
				log.Errorf("error deleting lab directory: %v", err)
				return err
			}
		}

		return nil
	}

	for _, labdir := range topos {
		if failedLabDirs[labdir] {
			log.Warnf(
				"keeping lab directory %s: the lab was not destroyed, so its state is kept for a later attempt",
				labdir,
			)

			continue
		}

		err := os.RemoveAll(labdir)
		if err != nil {
			log.Errorf("error deleting lab directory: %v", err)
		}
	}

	return nil
}

